#!/usr/bin/env node
/**
 * Emit robots.txt and sitemap.xml from the site's OWN canonical tags.
 *
 * WHY DERIVED RATHER THAN HAND-AUTHORED. A sitemap is a list of the site's
 * canonical URLs — which every page already declares in its head. Typing that
 * list a second time is the second-source-of-truth this repo's whole generator
 * pipeline exists to avoid, and it is the failure mode most likely here: three
 * of the eleven pages are GENERATED by cloning part-6's shell, and a slug that
 * moved would leave the sitemap advertising a URL that 404s while the page
 * itself is fine. Reading `rel=canonical` back off disk means the sitemap
 * cannot disagree with the pages it lists.
 *
 * Ordering: this MUST run after build:glossary / build:pictures / build:math,
 * for the same reason build:social-meta does — the clones rewrite their own
 * canonical, and this reads from disk after they have.
 *
 * WHY THE SITE NEEDED THESE AT ALL. docs.acfdashboard.com is the genuinely
 * indexable property — eleven clean routes, each with its own title,
 * description, canonical and social card — and it had neither file. The
 * DASHBOARD, which is an invite-only SPA with a single crawlable document,
 * is the one that gets asked about SEO; this is the site where it matters.
 *
 * Run:   npm run build:crawler
 * Check: npm run audit:crawler      (no browser, safe in any pipeline)
 */
import fs from 'node:fs';
import path from 'node:path';
import { PAGES } from './social-cards.config.mjs';

const ROOT = path.resolve(import.meta.dirname, '..');
const SITE = path.join(ROOT, 'public', 'site-b');
const PUBLIC = path.join(ROOT, 'public');
const CHECK = process.argv.includes('--check');

const ORIGIN = 'https://docs.acfdashboard.com';

/** Read a page's declared canonical. Missing is a hard error, not a skip: a
 *  page without one is an SEO defect, and silently omitting it from the
 *  sitemap would hide that rather than surface it. */
function canonicalOf(page) {
  const file = path.join(SITE, `${page}.html`);
  const html = fs.readFileSync(file, 'utf8');
  const match = html.match(/<link rel="canonical" href="([^"]+)"/);
  if (!match) throw new Error(`${page}.html declares no rel=canonical — cannot build a sitemap entry for it.`);
  const url = match[1];
  if (!url.startsWith(`${ORIGIN}/`) && url !== `${ORIGIN}/`) {
    throw new Error(`${page}.html canonical is off-origin: ${url}`);
  }
  return url;
}

const urls = PAGES.map(canonicalOf);
// The cover sorts first (it is the origin root); the rest read in slug order so
// a diff on this file shows what actually moved.
const ordered = [...new Set(urls)].sort((a, b) => (a.length - b.length) || a.localeCompare(b));

const robots = `# ACF Framework Documentation — crawler policy
#
# Generated by scripts/build-crawler-files.mjs. Do not edit by hand.
#
# The eleven clean routes below are the indexable surface, and each declares
# its own canonical. The RAW /site-b/* paths that back them are served too —
# next.config.mjs answers those with \`X-Robots-Tag: noindex\` so the clean
# route stays the single indexable copy — and they are disallowed here as well,
# because a header only reaches a crawler that has already fetched the page.
# The two together are belt and braces on the same duplicate-content risk.

User-agent: *
Allow: /
Disallow: /site-b/
Disallow: /api/

Sitemap: ${ORIGIN}/sitemap.xml
`;

const sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<!--
  Generated by scripts/build-crawler-files.mjs from each page's own
  <link rel="canonical">. Do not edit by hand — edit the page, or the rewrite
  table in next.config.mjs, and re-run \`npm run build:crawler\`.

  No <lastmod>: a hardcoded date rots silently, and a wrong one is worse than
  an absent one. \`npm run audit:crawler\` fails if this file stops matching the
  canonicals it was built from.
-->
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${ordered.map((url) => `  <url>\n    <loc>${url}</loc>\n  </url>`).join('\n')}
</urlset>
`;

const outputs = [
  { file: path.join(PUBLIC, 'robots.txt'), contents: robots },
  { file: path.join(PUBLIC, 'sitemap.xml'), contents: sitemap },
];

const drift = [];
for (const { file, contents } of outputs) {
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (current === contents) continue;
  if (CHECK) { drift.push(path.relative(ROOT, file)); continue; }
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, contents);
  console.log(`  ${current ? 'updated' : 'created'}  ${path.relative(ROOT, file)}`);
}

if (CHECK && drift.length) {
  console.error(`Crawler files are stale — run \`npm run build:crawler\`:\n  - ${drift.join('\n  - ')}`);
  process.exit(1);
}
console.log(CHECK
  ? `Crawler files match the canonicals (${ordered.length} URLs).`
  : `Crawler files generated: ${ordered.length} URLs.`);
